@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
.ui-root { --ui-primary: #1B2A4A; --ui-primary-text: #ffffff; --ui-bg: #F4F6F8; --ui-surface: #FDFEFF; --ui-surface-2: color-mix(in srgb, #14202F 6%, #FDFEFF); --ui-text: #14202F; --ui-muted: #5B6676; --ui-border: color-mix(in srgb, #14202F 14%, #F4F6F8); --ui-success: #2E7D5B; --ui-warning: #d97706; --ui-danger: #B3261E; --ui-info: #2563eb; --ui-radius: 8px; --ui-radius-sm: calc(8px / 2); --ui-space: 4px; --ui-shadow: 0 1px 2px rgb(16 24 40 / 0.06), 0 4px 12px rgb(16 24 40 / 0.06); --ui-font: 'Inter', system-ui, sans-serif; --ui-font-heading: 'Inter', system-ui, sans-serif; font-family: var(--ui-font); font-size: 15px; line-height: 1.5; color: var(--ui-text); background: var(--ui-bg); }
.ui-root h1, .ui-root h2, .ui-root h3 { font-family: var(--ui-font-heading); }

/* Page header */
.ui-root .ui-page { display: flex; flex-direction: column; gap: calc(var(--ui-space) * 10); max-width: 1120px; margin: 0 auto; padding: calc(var(--ui-space) * 10) calc(var(--ui-space) * 6); font-family: var(--ui-font); font-size: 15px; line-height: 1.5; color: var(--ui-text); }
.ui-root .ui-page-header { position: relative; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: calc(var(--ui-space) * 4); padding-bottom: calc(var(--ui-space) * 6); border-bottom: 1px solid var(--ui-border); }
.ui-root .ui-page-header::after { content: ""; position: absolute; left: 0; bottom: -1px; width: 64px; height: 2px; background: var(--ui-accent, var(--ui-info)); border-radius: var(--ui-radius-sm); }
.ui-root .ui-page-header > div:first-child { min-width: 0; }
.ui-root .ui-page-header h1 { margin: 0; font-family: var(--ui-font-heading); font-size: 32px; line-height: 1.2; font-weight: 700; letter-spacing: -0.01em; color: var(--ui-primary); }
.ui-root .ui-meta { margin: calc(var(--ui-space) * 2) 0 0; font-size: 15px; line-height: 1.5; color: var(--ui-muted); }
.ui-root .ui-page-header .ui-meta { margin-top: calc(var(--ui-space) * 2); }
.ui-root .ui-actions { display: flex; flex-wrap: wrap; align-items: center; gap: calc(var(--ui-space) * 3); flex-shrink: 0; }
@media (max-width: 899px) {
  .ui-root .ui-page { gap: calc(var(--ui-space) * 8); padding: calc(var(--ui-space) * 6) calc(var(--ui-space) * 4); }
  .ui-root .ui-page-header h1 { font-size: 26px; }
}

/* Stats */
.ui-root .ui-stat { display: flex; flex-direction: column; gap: calc(var(--ui-space) * 2); min-width: 0; padding: 24px; background: var(--ui-surface); border: 1px solid var(--ui-border); border-top: 2px solid var(--ui-primary); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); font-family: var(--ui-font); color: var(--ui-text); transition: border-color 150ms ease; }
.ui-root .ui-stat:hover { border-color: color-mix(in srgb, var(--ui-primary) 30%, var(--ui-border)); }
.ui-root .ui-stat-label { display: block; font-size: 14px; font-weight: 500; line-height: 1.4; color: var(--ui-muted); }
.ui-root .ui-stat-value { display: block; font-family: var(--ui-font-heading); font-size: 32px; font-weight: 700; line-height: 1.2; letter-spacing: -0.01em; color: var(--ui-primary); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.ui-root .ui-stat-note { display: block; font-size: 14px; line-height: 1.4; color: var(--ui-muted); }

/* Sections and layout */
.ui-root .ui-section { display: flex; flex-direction: column; gap: calc(var(--ui-space) * 6); padding-block: calc(var(--ui-space) * 10); color: var(--ui-text); font-family: var(--ui-font); font-size: 15px; line-height: 1.6; }
.ui-root .ui-section-title { position: relative; margin: 0; padding-top: calc(var(--ui-space) * 3); font-family: var(--ui-font-heading); font-size: 24px; font-weight: 600; line-height: 1.3; letter-spacing: -0.01em; color: var(--ui-primary); }
.ui-root .ui-section-title::before { content: ""; position: absolute; top: 0; left: 0; width: calc(var(--ui-space) * 10); height: 2px; border-radius: var(--ui-radius-sm); background: var(--ui-primary); }
.ui-root .ui-grid { display: grid; gap: calc(var(--ui-space) * 5); grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); align-items: start; }
.ui-root .ui-grid-2 { display: grid; gap: calc(var(--ui-space) * 5); grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; }
.ui-root .ui-grid-3 { display: grid; gap: calc(var(--ui-space) * 5); grid-template-columns: repeat(3, minmax(0, 1fr)); align-items: start; }
.ui-root .ui-grid-4 { display: grid; gap: calc(var(--ui-space) * 5); grid-template-columns: repeat(4, minmax(0, 1fr)); align-items: start; }
.ui-root .ui-row { display: flex; flex-wrap: wrap; align-items: center; gap: calc(var(--ui-space) * 4); }
.ui-root .ui-stack { display: flex; flex-direction: column; align-items: stretch; gap: calc(var(--ui-space) * 4); }
@media (max-width: 899px) {
  .ui-root .ui-grid-2 { grid-template-columns: minmax(0, 1fr); }
  .ui-root .ui-grid-3, .ui-root .ui-grid-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 599px) {
  .ui-root .ui-grid-3, .ui-root .ui-grid-4, .ui-root .ui-grid { grid-template-columns: minmax(0, 1fr); }
  .ui-root .ui-section { padding-block: calc(var(--ui-space) * 7); }
  .ui-root .ui-section-title { font-size: 20px; }
}

/* Lists */
.ui-root .ui-list { list-style: none; margin: 0; padding: 0; background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); overflow: hidden; }
.ui-root .ui-list-item { display: flex; align-items: center; justify-content: space-between; gap: calc(var(--ui-space) * 4); padding: calc(var(--ui-space) * 4) calc(var(--ui-space) * 5); border-top: 1px solid var(--ui-border); color: var(--ui-text); transition: background-color 150ms ease, box-shadow 150ms ease; }
.ui-root .ui-list-item:first-child { border-top: 0; }
.ui-root .ui-list-item:hover, .ui-root .ui-list-item:focus-within { background: var(--ui-surface-2); }
.ui-root .ui-list-item.is-active { box-shadow: inset 3px 0 0 var(--ui-primary); }
.ui-root .ui-list-item.is-disabled { color: var(--ui-muted); }
.ui-root .ui-list-main { display: flex; flex-direction: column; gap: var(--ui-space); min-width: 0; font-size: 15px; line-height: 1.5; }
.ui-root .ui-list-main strong { font-family: var(--ui-font-heading); font-weight: 600; color: var(--ui-text); }
.ui-root .ui-list-item.is-disabled .ui-list-main strong { color: var(--ui-muted); }
.ui-root .ui-list-side { display: flex; align-items: center; justify-content: flex-end; flex-wrap: wrap; gap: calc(var(--ui-space) * 2); flex-shrink: 0; }
@media (max-width: 600px) {
  .ui-root .ui-list-item { flex-wrap: wrap; align-items: flex-start; }
  .ui-root .ui-list-side { justify-content: flex-start; }
}

/* Tables */
.ui-root .ui-table-wrap { width: 100%; overflow-x: auto; -webkit-overflow-scrolling: touch; background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); }
.ui-root .ui-table { width: 100%; border-collapse: separate; border-spacing: 0; font-family: var(--ui-font); font-size: 15px; line-height: 1.5; color: var(--ui-text); background: var(--ui-surface); }
.ui-root .ui-table th, .ui-root .ui-table td { padding: calc(var(--ui-space) * 4) calc(var(--ui-space) * 5); text-align: left; vertical-align: middle; border-bottom: 1px solid var(--ui-border); }
.ui-root .ui-table th { font-family: var(--ui-font-heading); font-size: 14px; font-weight: 600; line-height: 1.4; color: var(--ui-muted); background: var(--ui-surface-2); white-space: nowrap; }
.ui-root .ui-table td { font-size: 15px; font-variant-numeric: tabular-nums; color: var(--ui-text); }
.ui-root .ui-table th:last-child, .ui-root .ui-table td:last-child { text-align: right; }
.ui-root .ui-table tbody tr:last-child td { border-bottom: 0; }
.ui-root .ui-table tbody tr { transition: background-color 150ms ease; }
.ui-root .ui-table tbody tr:hover { background: var(--ui-surface-2); }
.ui-root .ui-table tbody tr.is-active { background: var(--ui-surface-2); box-shadow: inset 3px 0 0 var(--ui-primary); }
.ui-root .ui-table tbody tr.is-disabled td { color: var(--ui-muted); }

/* Buttons and links */
.ui-root .ui-btn { display: inline-flex; align-items: center; justify-content: center; gap: var(--ui-space); min-height: calc(var(--ui-space) * 10); padding: calc(var(--ui-space) * 2) calc(var(--ui-space) * 4); border: 1px solid transparent; border-radius: var(--ui-radius); font-family: var(--ui-font); font-size: 15px; font-weight: 600; line-height: 1.25; text-decoration: none; white-space: nowrap; cursor: pointer; transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease; }
.ui-root .ui-btn:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: 2px; }
.ui-root .ui-btn-primary { background: var(--ui-primary); color: var(--ui-primary-text); border-color: var(--ui-primary); }
.ui-root .ui-btn-primary:hover, .ui-root .ui-btn-primary.is-active { background: color-mix(in srgb, var(--ui-primary) 88%, var(--ui-text)); border-color: color-mix(in srgb, var(--ui-primary) 88%, var(--ui-text)); }
.ui-root .ui-btn-secondary { background: var(--ui-surface); color: var(--ui-primary); border-color: var(--ui-border); }
.ui-root .ui-btn-secondary:hover, .ui-root .ui-btn-secondary.is-active { background: var(--ui-surface-2); border-color: var(--ui-primary); }
.ui-root .ui-btn-ghost { background: transparent; color: var(--ui-primary); border-color: transparent; }
.ui-root .ui-btn-ghost:hover, .ui-root .ui-btn-ghost.is-active { background: var(--ui-surface-2); color: var(--ui-text); }
.ui-root .ui-btn-danger { background: var(--ui-danger); color: var(--ui-primary-text); border-color: var(--ui-danger); }
.ui-root .ui-btn-danger:hover, .ui-root .ui-btn-danger.is-active { background: color-mix(in srgb, var(--ui-danger) 88%, var(--ui-text)); border-color: color-mix(in srgb, var(--ui-danger) 88%, var(--ui-text)); }
.ui-root .ui-btn-sm { min-height: calc(var(--ui-space) * 8); padding: var(--ui-space) calc(var(--ui-space) * 3); font-size: 14px; }
.ui-root .ui-btn.is-disabled, .ui-root .ui-btn:disabled { opacity: 0.5; cursor: not-allowed; pointer-events: none; }
.ui-root .ui-link { color: var(--ui-primary); font-family: var(--ui-font); font-size: 15px; font-weight: 500; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; transition: color 150ms ease, text-decoration-thickness 150ms ease; }
.ui-root .ui-link:hover, .ui-root .ui-link.is-active { color: var(--ui-text); text-decoration-thickness: 2px; }
.ui-root .ui-link:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: 2px; border-radius: var(--ui-radius-sm); }

/* Cards */
.ui-root .ui-card { display: flex; flex-direction: column; min-width: 0; overflow: hidden; background: var(--ui-surface); color: var(--ui-text); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); font-family: var(--ui-font); }
.ui-root .ui-card-header { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; padding: 20px 24px 16px; border-bottom: 1px solid var(--ui-border); }
.ui-root .ui-card-header h3 { margin: 0; font-family: var(--ui-font-heading); font-size: 18px; font-weight: 600; line-height: 1.3; color: var(--ui-text); min-width: 0; }
.ui-root .ui-card-body { flex: 1 1 auto; padding: 16px 24px; color: var(--ui-text); font-size: 15px; line-height: 1.6; }
.ui-root .ui-card-body p { margin: 0; color: var(--ui-muted); }
.ui-root .ui-card-body p + p { margin-top: 12px; }
.ui-root .ui-card-footer { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; padding: 12px 24px 20px; border-top: 1px solid var(--ui-border); background: var(--ui-surface-2); }
.ui-root a.ui-card-link { display: flex; text-decoration: none; color: var(--ui-text); cursor: pointer; transition: border-color 150ms ease, box-shadow 150ms ease; }
.ui-root a.ui-card-link:hover { border-color: color-mix(in srgb, var(--ui-primary) 35%, var(--ui-border)); }
.ui-root a.ui-card-link:hover .ui-card-header h3 { color: var(--ui-primary); }
.ui-root a.ui-card-link:focus-visible { outline: 2px solid var(--ui-primary); outline-offset: 2px; }
.ui-root .ui-card.is-active { border-color: var(--ui-primary); box-shadow: 0 0 0 1px var(--ui-primary), var(--ui-shadow); }

/* Badges and people */
.ui-root .ui-badge { display: inline-flex; align-items: center; gap: 4px; padding: 4px 12px; border-radius: 999px; border: 1px solid transparent; font-family: var(--ui-font); font-size: 14px; font-weight: 600; line-height: 1.2; white-space: nowrap; color: var(--ui-text); background: var(--ui-surface-2); border-color: var(--ui-border); }
.ui-root .ui-badge-success { color: color-mix(in srgb, var(--ui-success) 75%, var(--ui-text)); background: color-mix(in srgb, var(--ui-success) 12%, var(--ui-surface)); border-color: color-mix(in srgb, var(--ui-success) 30%, var(--ui-surface)); }
.ui-root .ui-badge-warning { color: color-mix(in srgb, var(--ui-warning) 75%, var(--ui-text)); background: color-mix(in srgb, var(--ui-warning) 18%, var(--ui-surface)); border-color: color-mix(in srgb, var(--ui-warning) 40%, var(--ui-surface)); }
.ui-root .ui-badge-danger { color: color-mix(in srgb, var(--ui-danger) 80%, var(--ui-text)); background: color-mix(in srgb, var(--ui-danger) 10%, var(--ui-surface)); border-color: color-mix(in srgb, var(--ui-danger) 30%, var(--ui-surface)); }
.ui-root .ui-badge-info { color: color-mix(in srgb, var(--ui-info) 75%, var(--ui-text)); background: color-mix(in srgb, var(--ui-info) 10%, var(--ui-surface)); border-color: color-mix(in srgb, var(--ui-info) 30%, var(--ui-surface)); }
.ui-root .ui-badge-neutral { color: var(--ui-muted); background: var(--ui-surface-2); border-color: var(--ui-border); }
.ui-root .ui-avatar { display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; width: 40px; height: 40px; border-radius: 999px; border: 1px solid var(--ui-border); background: var(--ui-primary); color: var(--ui-primary-text); font-family: var(--ui-font-heading); font-size: 14px; font-weight: 600; letter-spacing: 0.02em; line-height: 1; text-transform: uppercase; user-select: none; }

/* Progress */
.ui-root .ui-progress { display: block; position: relative; width: 100%; height: 4px; margin: calc(var(--ui-space) * 4) 0; overflow: hidden; border-radius: var(--ui-radius); background: var(--ui-surface-2); box-shadow: inset 0 0 0 1px var(--ui-border); }
.ui-root .ui-progress > span { display: block; height: 100%; max-width: 100%; border-radius: inherit; background: var(--ui-primary); transition: width 200ms ease; }

/* Details */
.ui-root .ui-kv { display: grid; grid-template-columns: minmax(8rem, max-content) minmax(0, 1fr); column-gap: calc(var(--ui-space) * 6); row-gap: 0; margin: 0; padding: calc(var(--ui-space) * 1) calc(var(--ui-space) * 5); background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); font-family: var(--ui-font); font-size: 15px; line-height: 1.5; color: var(--ui-text); }
.ui-root .ui-kv > dt { margin: 0; padding: calc(var(--ui-space) * 3) 0; border-top: 1px solid var(--ui-border); color: var(--ui-muted); font-size: 14px; font-weight: 500; line-height: 1.4; }
.ui-root .ui-kv > dd { margin: 0; padding: calc(var(--ui-space) * 3) 0; border-top: 1px solid var(--ui-border); color: var(--ui-text); font-size: 15px; font-weight: 500; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; min-width: 0; }
.ui-root .ui-kv > dt:first-child, .ui-root .ui-kv > dd:nth-child(2) { border-top: 0; }
.ui-root .ui-kv > dt:first-child { padding-top: calc(var(--ui-space) * 3); }
@media (max-width: 599px) {
  .ui-root .ui-kv { grid-template-columns: minmax(0, 1fr); column-gap: 0; }
  .ui-root .ui-kv > dt { padding-bottom: 0; border-top: 1px solid var(--ui-border); }
  .ui-root .ui-kv > dd { padding-top: calc(var(--ui-space) * 1); border-top: 0; }
  .ui-root .ui-kv > dt:first-child { border-top: 0; }
}

/* Messages and empty states */
.ui-root .ui-empty { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 8px; padding: 40px 24px; background: var(--ui-surface); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); box-shadow: var(--ui-shadow); color: var(--ui-text); }
.ui-root .ui-empty-title { margin: 0; font-family: var(--ui-font-heading); font-size: 18px; font-weight: 600; line-height: 1.3; color: var(--ui-text); }
.ui-root .ui-empty-text { margin: 0 0 16px; max-width: 44ch; font-size: 15px; line-height: 1.5; color: var(--ui-muted); }
.ui-root .ui-alert { display: flex; align-items: flex-start; gap: 12px; padding: 12px 16px; background: var(--ui-surface); border: 1px solid var(--ui-border); border-left: 3px solid var(--ui-info); border-radius: var(--ui-radius); color: var(--ui-text); font-family: var(--ui-font); font-size: 14px; line-height: 1.5; }
.ui-root .ui-alert::before { content: ""; flex: 0 0 8px; width: 8px; height: 8px; margin-top: 6px; border-radius: 50%; background: var(--ui-info); }
.ui-root .ui-alert-info { background: color-mix(in srgb, var(--ui-info) 8%, var(--ui-surface)); border-left-color: var(--ui-info); }
.ui-root .ui-alert-info::before { background: var(--ui-info); }
.ui-root .ui-alert-success { background: color-mix(in srgb, var(--ui-success) 10%, var(--ui-surface)); border-left-color: var(--ui-success); }
.ui-root .ui-alert-success::before { background: var(--ui-success); }
.ui-root .ui-alert-warning { background: color-mix(in srgb, var(--ui-warning) 12%, var(--ui-surface)); border-left-color: var(--ui-warning); }
.ui-root .ui-alert-warning::before { background: var(--ui-warning); }
.ui-root .ui-alert-danger { background: color-mix(in srgb, var(--ui-danger) 8%, var(--ui-surface)); border-left-color: var(--ui-danger); }
.ui-root .ui-alert-danger::before { background: var(--ui-danger); }

/* Timeline */
.ui-root .ui-timeline { list-style: none; margin: 0; padding: 0 0 0 calc(var(--ui-space) * 2); display: flex; flex-direction: column; font-family: var(--ui-font); }
.ui-root .ui-timeline-item { position: relative; margin: 0; padding: 0 0 calc(var(--ui-space) * 6) calc(var(--ui-space) * 6); border-left: 1px solid var(--ui-border); }
.ui-root .ui-timeline-item:last-child { padding-bottom: 0; border-left-color: transparent; }
.ui-root .ui-timeline-item::before { content: ""; position: absolute; left: -5px; top: calc(var(--ui-space) * 1.5); width: calc(var(--ui-space) * 2.5); height: calc(var(--ui-space) * 2.5); border-radius: 50%; background: var(--ui-primary); box-shadow: 0 0 0 calc(var(--ui-space) * 1) var(--ui-surface); }
.ui-root .ui-timeline-item p { margin: 0; font-size: 15px; line-height: 1.5; color: var(--ui-text); }
.ui-root .ui-timeline-time { display: inline-block; margin: 0 0 calc(var(--ui-space) * 1.5); padding: calc(var(--ui-space) * 1) calc(var(--ui-space) * 2.5); border-radius: 999px; background: var(--ui-surface-2); border: 1px solid var(--ui-border); font-size: 14px; font-weight: 600; line-height: 1.3; color: var(--ui-text); transition: background-color 0.15s ease, border-color 0.15s ease; }
.ui-root .ui-timeline-item:hover .ui-timeline-time { border-color: var(--ui-primary); }

/* Pictures, maps and charts */
.ui-root .ui-media { position: relative; display: flex; align-items: center; justify-content: center; width: 100%; aspect-ratio: 16 / 9; overflow: hidden; background: var(--ui-surface-2); color: var(--ui-muted); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); font-family: var(--ui-font); font-size: 14px; line-height: 1.5; }
.ui-root .ui-media img, .ui-root .ui-media picture, .ui-root .ui-media video { display: block; width: 100%; height: 100%; object-fit: cover; }
.ui-root .ui-map { position: relative; width: 100%; height: 320px; overflow: hidden; background-color: var(--ui-surface-2); background-image:
    repeating-linear-gradient(0deg, var(--ui-border) 0 1px, transparent 1px 48px),
    repeating-linear-gradient(90deg, var(--ui-border) 0 1px, transparent 1px 48px); border: 1px solid var(--ui-border); border-radius: var(--ui-radius); font-family: var(--ui-font); }
.ui-root .ui-map-pin { position: absolute; display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; width: 28px; height: 28px; transform: translate(-50%, -50%); padding: 0; background: var(--ui-primary); color: var(--ui-primary-text); border: 2px solid var(--ui-surface); border-radius: 999px; box-shadow: var(--ui-shadow); font-family: var(--ui-font); font-size: 14px; font-weight: 600; line-height: 1; transition: background-color 150ms ease-out; }
.ui-root .ui-map-pin:hover, .ui-root .ui-map-pin:focus-visible { background: var(--ui-secondary, var(--ui-primary)); outline: none; }
